import type { ReactNode } from "react";
import type { PlanName } from "@/lib/plans";
import { cn } from "@/lib/utils";
import { PlanCard, type UpgradeFeature } from "./plan-card";
import styles from "../PricingPage.module.css";

// Synchronous and client-compatible; callers own authentication and actions.
export function PricingCards({
  price,
  freeAction,
  premiumAction,
  dialog = false,
  landing = false,
  currentPlan,
  feature,
}: {
  price: { symbol: string; amount: number };
  freeAction: ReactNode;
  premiumAction: ReactNode;
  dialog?: boolean;
  landing?: boolean;
  currentPlan?: PlanName | null;
  feature?: UpgradeFeature;
}) {
  return (
    <section
      className={cn(
        styles.body,
        styles.plans,
        "mx-auto grid w-full min-w-0 max-w-285 grid-cols-1 gap-6 text-[15px] leading-[1.55] [font-family:var(--font-plus-jakarta),system-ui,sans-serif] min-[700px]:grid-cols-[minmax(0,1fr)_minmax(0,1.15fr)]",
        landing && "pricing-stack max-w-245",
      )}
      data-plan-cards
      data-dialog-cards={dialog || undefined}
      aria-label="Plans"
    >
      {(["FREE", "PAID"] as const).map((plan) => {
        const premium = plan === "PAID";
        return (
          <PlanCard
            key={plan}
            premium={premium}
            compactMobile={!dialog}
            price={price}
            heading={dialog || landing ? "h3" : "h2"}
            headingId={
              landing ? (premium ? "premium-title" : "free-title") : undefined
            }
            current={currentPlan === plan}
            feature={dialog ? feature : undefined}
            className={cn(
              styles.plan,
              "pricing-card",
              landing &&
                "gap-3.5 px-7 py-6 max-[699px]:px-5 max-[699px]:py-5 min-[700px]:[&_.pricing-stats]:mt-3 min-[700px]:[&_[data-upgrade-stat]]:py-3 min-[700px]:[&_.upgrade-features]:gap-2 [&_.upgrade-features>li]:min-h-6 min-[700px]:[&.pricing-premium_.upgrade-features>li]:py-1 [[data-theme=light]_&]:[&_[data-upgrade-stat]]:ring-1 [[data-theme=light]_&]:[&_[data-upgrade-stat]]:ring-upgrade-border [[data-theme=light]_&]:[&_[data-upgrade-stat]]:shadow-[0_3px_8px_color-mix(in_srgb,var(--upgrade-text)_8%,transparent)]",
              landing &&
                "[[data-theme=light]_&]:[&_[data-upgrade-stat]]:hover:pointer-fine:ring-upgrade-ok [[data-theme=light]_&]:[&_[data-upgrade-stat]]:hover:pointer-fine:shadow-[0_8px_20px_-6px_var(--upgrade-glow),inset_0_0_0_1px_var(--upgrade-ok)]",
              premium ? "pricing-premium" : "pricing-free",
            )}
            action={
              <div
                className={cn(
                  styles.actionSlot,
                  "mt-auto pt-3",
                  premium && styles.primary,
                )}
              >
                {premium ? premiumAction : freeAction}
              </div>
            }
          />
        );
      })}
    </section>
  );
}
